type User = { id: string; name: string };
type Post = { id: number; title: string };
type Follower = { id: number; name: string };

async function getUser(id: string): Promise<User> {
  return (await fetch(`https://api.example.com/users/${id}`)).json();
}
async function getPosts(id: string): Promise<Post[]> {
  return (await fetch(`https://api.example.com/users/${id}/posts`)).json();
}
async function getFollowers(id: string): Promise<Follower[]> {
  return (await fetch(`https://api.example.com/users/${id}/followers`)).json();
}

export default async function ProfilePage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;

  // Start all three requests, then await together (parallel, no waterfall)
  const [user, posts, followers] = await Promise.all([
    getUser(id),
    getPosts(id),
    getFollowers(id),
  ]);

  return (
    <main>
      <h1>{user.name}</h1>
      <p>{posts.length} posts &middot; {followers.length} followers</p>
    </main>
  );
}

