// app/api/weather/route.ts
import { NextResponse } from 'next/server';

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const city = searchParams.get('city');
  if (!city) {
    return NextResponse.json({ error: 'city is required' }, { status: 400 });
  }

  const upstream = new URL('https://api.weather.example.com/current');
  upstream.searchParams.set('q', city);
  // Secret stays on the server, never shipped to the client
  upstream.searchParams.set('key', process.env.WEATHER_API_KEY ?? '');

  const res = await fetch(upstream, { next: { revalidate: 300 } });
  if (!res.ok) {
    return NextResponse.json(
      { error: 'Upstream error' },
      { status: res.status }
    );
  }
  const data = await res.json();
  return NextResponse.json({ city, temp: data.temp_c });
}

