import Link from 'next/link';

type Product = { id: number; name: string; category: string };

async function getProducts(category?: string): Promise<Product[]> {
  const url = new URL('https://api.example.com/products');
  if (category) url.searchParams.set('category', category);
  return (await fetch(url, { next: { revalidate: 60 } })).json();
}

export default async function ProductsPage({
  searchParams,
}: {
  searchParams: Promise<{ category?: string }>;
}) {
  const { category } = await searchParams;
  const products = await getProducts(category);
  const categories = ['all', 'books', 'electronics'];

  return (
    <main>
      <nav>
        {categories.map((c) => (
          <Link
            key={c}
            href={c === 'all' ? '/products' : `/products?category=${c}`}
          >
            {c}
          </Link>
        ))}
      </nav>
      <ul>
        {products.map((p) => (
          <li key={p.id}>{p.name}</li>
        ))}
      </ul>
    </main>
  );
}

